SELECT CASE WHEN a.balance >= 80000 THEN 'high' WHEN a.balance >= 17000 THEN 'mid' ELSE 'low' END AS balance_bucket, SUM(CASE WHEN t.txn_type = 'CREDIT' THEN t.amount ELSE 0 END) AS credit_amount, ROUND((100 * SUM(CASE WHEN t.merchant = 'Grab' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_grab FROM transactions t INNER JOIN accounts a ON t.account_id = a.id GROUP BY CASE WHEN a.balance >= 80000 THEN 'high' WHEN a.balance >= 17000 THEN 'mid' ELSE 'low' END ORDER BY credit_amount DESC;
